IN: tl.constexpr = float8_info.min,\n    FP8_MAX: tl.constexpr = float8_info.max,\n):\n    q_block_global_idx = tl.program_id(0)\n    kv_head_idx = tl.program_id(1)\n\n    seq_idx = find_seq_idx(query_start_len_ptr, q_block_global_idx, num_seqs,\n                           BLOCK_Q, True)\n\n    q_block_start_idx = tl.load(query_start_len_ptr +\n                                seq_idx) // BLOCK_Q + seq_idx\n\n    q_block_local_idx = q_block_global_idx - q_block_start_idx\n\n    cur_batch_in_all_start_index = tl.load(query_start_len_ptr + seq_idx)\n    cur_batch_in_all_stop_index = tl.load(query_start_len_ptr + seq_idx + 1)\n\n    cur_batch_query_len = cur_batch_in_all_stop_index \\\n        - cur_batch_in_all_start_index\n\n    if q_block_local_idx * BLOCK_Q >= cur_batch_query_len:\n        return\n\n    offs_m = tl.arange(0, BLOCK_M)\n    offs_d = tl.arange(0, HEAD_SIZE_PADDED)\n    offs_t = tl.arange(0, TILE_SIZE)\n    query_pos = q_block_local_idx * BLOCK_Q + offs_m // num_queries_per_kv\n\n    query_offset_0 = cur_batch_in_all_start_index + query_pos\n    query_offset_1 = kv_head_idx * num_queries_per_kv + \\\n        offs_m % num_queries_per_kv\n    query_offset = (query_offset_0[:, None] * query_stride_0 +\n                    query_offset_1[:, None] * query_stride_1 + offs_d[None, :])\n\n    dim_mask = tl.where(offs_d < HEAD_SIZE, 1, 0).to(tl.int1)\n    query_mask_0 = tl.where(query_pos < cur_batch_query_len, 1, 0).to(tl.int1)\n    query_mask_1 = tl.where(query_offset_1 < num_query_heads, 1, 0).to(tl.int1)\n\n    # Q : (BLOCK_M, HEAD_SIZE_PADDED)\n    Q = tl.load(\n        query_ptr + query_offset,\n        mask=dim_mask[None, :] & query_mask_0[:, None] & query_mask_1[:, None],\n        other=0.0,\n    )\n\n    block_table_offset = seq_idx * block_table_stride\n\n    if not USE_SINKS:\n        M = tl.full([BLOCK_M], float(\"-inf\"), dtype=tl.float32)\n    else:\n        M = tl.load(\n            sink_ptr + query_offset_1,\n            mask=query_mask_1,\n            other=float(\"-inf\"),\n        ).to(dtype=tl.float32)\n\n    L = tl.full([BLOCK_M], 1.0, dtype=tl.float32)\n    acc = tl.zeros([BLOCK_M, HEAD_SIZE_PADDED], dtype=tl.float32)\n\n    # context length for this particular sequences\n    context_len = tl.load(seq_lens_ptr + seq_idx) - cur_batch_query_len\n\n    # alibi slope for this head\n    if USE_ALIBI_SLOPES:\n        alibi_slope = tl.load(alibi_slopes_ptr + query_offset_1,\n                              mask=query_mask_1,\n                              other=0.0)\n\n    # query-query attention bias\n    if USE_QQ_BIAS:\n        qq_bias_row_ptrs = (qq_bias_ptr + query_pos[:, None] * qq_bias_stride_0\n                            )  # shape: [BLOCK_M]\n\n    # compute the length of the longest sequence prefix spanned by any\n    # query token in the current q_block (q_block_local_idx)\n    max_seq_prefix_len = context_len + q_block_local_idx * BLOCK_Q + (\n        BLOCK_M - 1) // num_queries_per_kv + 1\n\n    # adjust for potential padding in the last q_block by considering the\n    # actual sequence length\n    max_seq_prefix_len = tl.minimum(max_seq_prefix_len, tl.load(seq_lens_ptr + seq_idx))\n\n    # calculate the number of tiles that need to be processed to\n    # cover the longest sequence prefix (due to causal masking, tiles beyond\n    # this prefix can be skipped)\n    num_tiles = cdiv_fn(max_seq_prefix_len, TILE_SIZE)\n\n    # iterate through tiles\n    for j in range(0, num_tiles):\n        tile_start = j * TILE_SIZE\n        tile_end = tile_start + TILE_SIZE - 1\n        \n        # Check if we should skip this tile due to sliding window\n        # For sliding window attention, a tile can be skipped if it's completely\n        # outside the valid attention window for ALL queries in this block\n        if SLIDING_WINDOW > 0:\n            # For each query, the valid key range is:\n            # context_len + query_pos[i] - SLIDING_WINDOW < seq_offset < context_len + query_pos[i] + 1\n            # So